solution:
a, b, c = map(int, input().split())
x, y, z = sorted([a, b, c])
if x + y <= z:
    print("INVALID")
elif x == y == z:
    print("EQUILATERAL")
elif x == y or y == z:
    print("ISOSCELES")
elif x * x + y * y == z * z:
    print("RIGHT")
else:
    print("SCALENE")

example.code:
a, b, c = map(int, input().split())
# sorted()로 작은 순서로 정렬하면 low가 가장 작고 high가 가장 커요.
low, mid, high = sorted([a, b, c])
if high - low >= 50:
    print("점수 차이가 커요")
elif low == mid or mid == high:
    print("같은 점수가 있어요")
else:
    print("고르게 퍼져 있어요")

