a, b, c = map(int, input().split())
x, y, z = sorted([a, b, c])
if x == y == z:
    print("TRIPLE")
elif x == y or y == z:
    print("PAIR")
elif y == x + 1 and z == y + 1:
    print("STRAIGHT")
else:
    print("NONE")
